<?php declare(strict_types=1); $title = 'Compra #' . $purchase['id']; ?>
<section><div class="mb-6 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><a href="<?= e($baseUrl) ?>/compras" class="text-sm font-semibold text-emerald-800">← Historial de compras</a><h1 class="mt-3 text-3xl font-bold text-slate-900">Compra #<?= e($purchase['id']) ?></h1><p class="mt-2 text-sm text-slate-600"><?= e(date('d/m/Y H:i', strtotime($purchase['fecha']))) ?> · Registró <?= e($purchase['usuario']) ?></p></div><?php if ($purchase['estado']==='registrada' && can('compras.anular')): ?><form method="post" action="<?= e($baseUrl) ?>/compras/anular" onsubmit="return confirm('¿Anular esta compra? Solo se permite si los lotes no fueron vendidos ni modificados.');"><input type="hidden" name="_csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= e($purchase['id']) ?>"><button class="rounded-lg border border-red-300 px-4 py-3 text-sm font-semibold text-red-700">Anular compra</button></form><?php endif; ?></div>
<?php if ($success): ?><div role="status" class="mb-5 rounded-lg border border-emerald-200 bg-emerald-50 px-4 py-3 text-sm text-emerald-900"><?= e($success) ?></div><?php endif; ?><?php if ($error): ?><div role="alert" class="mb-5 rounded-lg border border-red-200 bg-red-50 px-4 py-3 text-sm text-red-800"><?= e($error) ?></div><?php endif; ?>
<div class="mb-6 grid gap-4 rounded-xl border border-slate-200 bg-white p-5 sm:grid-cols-3"><div><div class="text-xs uppercase text-slate-500">Proveedor</div><div class="mt-1 font-semibold"><?= e($purchase['proveedor']) ?></div></div><div><div class="text-xs uppercase text-slate-500">Documento</div><div class="mt-1 font-semibold"><?= e($purchase['numero_documento'] ?: '—') ?></div></div><div><div class="text-xs uppercase text-slate-500">Estado</div><div class="mt-1 font-semibold"><?= e(ucfirst($purchase['estado'])) ?></div></div><?php if ($purchase['observaciones']): ?><div class="sm:col-span-3"><div class="text-xs uppercase text-slate-500">Observaciones</div><div class="mt-1"><?= e($purchase['observaciones']) ?></div></div><?php endif; ?></div>
<div class="overflow-x-auto rounded-xl border border-slate-200 bg-white"><table class="min-w-full divide-y divide-slate-200 text-sm"><thead class="bg-slate-50 text-left text-xs uppercase text-slate-600"><tr><?php foreach (['Producto', 'Lote', 'Vencimiento', 'Cantidad', 'Costo unitario', 'Subtotal'] as $label): ?><th class="px-4 py-3"><?= e($label) ?></th><?php endforeach; ?></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach ($items as $item): ?><tr><td class="px-4 py-3"><strong><?= e($item['producto']) ?></strong><div class="text-xs text-slate-500"><?= e($item['codigo']) ?></div></td><td class="px-4 py-3"><?= e($item['codigo_lote']) ?></td><td class="px-4 py-3"><?= e($item['fecha_vencimiento'] ? date('d/m/Y', strtotime($item['fecha_vencimiento'])) : '—') ?></td><td class="px-4 py-3"><?= e(number_format((float)$item['cantidad'], 3)) ?> <?= e($item['unidad_medida']) ?></td><td class="px-4 py-3">S/ <?= e(number_format((float)$item['costo_unitario'], 4)) ?></td><td class="px-4 py-3">S/ <?= e(number_format((float)$item['subtotal'], 2)) ?></td></tr><?php endforeach; ?><tr class="bg-slate-50 font-bold"><td colspan="5" class="px-4 py-4 text-right">TOTAL</td><td class="px-4 py-4">S/ <?= e(number_format((float)$purchase['total'], 2)) ?></td></tr></tbody></table></div></section>
